var mostPopularCreator = function(creators, ids, views) {
    let n = creators.length;
    let creatorStats = new Map();

    for (let i = 0; i < n; i++) {
        let creator = creators[i];
        let id = ids[i];
        let view = views[i];

        if (!creatorStats.has(creator)) {
            creatorStats.set(creator, { totalViews: 0, bestId: id, bestViews: view });
        }
        let stats = creatorStats.get(creator);
        stats.totalViews += view;
        if (view > stats.bestViews || (view === stats.bestViews && id < stats.bestId)) {
            stats.bestId = id;
            stats.bestViews = view;
        }
    }

    let maxTotal = 0;
    for (let stats of creatorStats.values()) {
        maxTotal = Math.max(maxTotal, stats.totalViews);
    }

    let result = [];
    for (let [creator, stats] of creatorStats) {
        if (stats.totalViews === maxTotal) {
            result.push([creator, stats.bestId]);
        }
    }

    return result;
};

